"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["60309"],{96008(e){e.exports=JSON.parse('{"id":"FIN-458","slug":"licensing-model","term":"Licensing Model","also_known_as":[],"difficulty":"Intermediate","definition":"A licensing model is a business model in which a company allows others to use its intellectual property, such as a patent, brand, technology, software or content, in exchange for fees or royalties.","explanation":["Instead of producing and selling products itself, a company can earn money by letting others use what it owns. The licensee gains the right to use the intellectual property under agreed terms, and the licensor receives payment.","Examples include technology companies licensing patents to device makers, entertainment companies licensing characters for toys and clothing, software companies licensing their programs to businesses and universities licensing research discoveries to manufacturers.","Payments can be an upfront fee, a royalty based on sales, a fixed annual fee or a combination. For example, a brand owner might license its logo to a clothing manufacturer in exchange for 8% of the wholesale price of every item sold.","Licensing can be highly profitable, because the licensor does not bear the costs of manufacturing, distribution or retail. It also allows a company to reach markets or industries it could not easily enter on its own.","The risks include loss of control over how the intellectual property is used, potential damage to the brand if licensees provide poor quality and the need to monitor and enforce licence agreements."],"note":"","total":1500,"prev":{"slug":"libor","term":"LIBOR"},"next":{"slug":"life-expectancy","term":"Life Expectancy"}}')}}]);